window.kbPageData["views/entry/k-7ce6f443ba66ca17"] = {"key":"entry/k-7ce6f443ba66ca17","state":{"route":"entry/k-7ce6f443ba66ca17"},"node":{"id":"k-7ce6f443ba66ca17","mode":"k","title":"剩余价值理论 · 剩余价值","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["概念与词义"],"出处性质":["理论手册"],"学科":["经济"],"来源主题":["马克思主义政治经济学"],"资料类别":["非时政"]},"seeAlso":["k-100c5c0a63057296","k-13a1b790d5c575c8","k-882e2bbbc89e900c"],"directorySummary":"一、剩余价值\n1.含义：剩余价值是雇佣工人所创造的并被资本家无偿占有的超过劳动力价值的那部分\n价值。\n2.生产方法：绝对剩余价值是指在必要劳动时间不变的条件下，通过延长工作时间所获\n得的剩余价值；\n相对剩余价值是指在工作时间不变的条件下，由于缩短必要劳动时间而相对延长剩余劳\n动时间所生产的剩余价值。…","sources":[{"id":"71cb8452916f2c46","label":"剩余价值理论 · 剩余价值","topic":"马克思主义政治经济学","category":"非时政","text":"一、剩余价值\n1.含义：剩余价值是雇佣工人所创造的并被资本家无偿占有的超过劳动力价值的那部分\n价值。\n2.生产方法：绝对剩余价值是指在必要劳动时间不变的条件下，通过延长工作时间所获\n得的剩余价值；\n相对剩余价值是指在工作时间不变的条件下，由于缩短必要劳动时间而相对延长剩余劳\n动时间所生产的剩余价值。相对剩余价值是各个资本家追逐超额剩余价值而实现的。\n（超额剩余价值是指单个资本家通过提高劳动生产率使商品的个别价值低于社会价值\n而比一般资本家多得的那部分价值。）\n（粉笔敲黑板：理解并能够区分绝对剩余价值、相对剩余价值和超额剩余价值）","source":{"doc":"3ccc56f4000d1642c2d1","first":9,"last":9,"page":9,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{"k-100c5c0a63057296":{"id":"k-100c5c0a63057296","mode":"k","type":"概念与词义","title":"超额剩余价值","qs":[],"count":0},"k-13a1b790d5c575c8":{"id":"k-13a1b790d5c575c8","mode":"k","type":"概念与词义","title":"绝对剩余价值","qs":[],"count":0},"k-882e2bbbc89e900c":{"id":"k-882e2bbbc89e900c","mode":"k","type":"概念与词义","title":"相对剩余价值","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-7ce6f443ba66ca17":[]}};
